"""Metadata checks shared by the gfx950 N3072/K1536 FP8 candidates."""

import torch


def validate_inputs(a, b, a_scale, b_scale, supported_m):
    tensors = (a, b, a_scale, b_scale)
    if not all(isinstance(t, torch.Tensor) and t.ndim == 2 for t in tensors):
        raise ValueError("expected four two-dimensional tensors")
    if any(t.layout != torch.strided or not t.is_contiguous() for t in tensors):
        raise ValueError("expected contiguous K-major tensors")
    if any(t.is_conj() or t.is_neg() for t in tensors):
        raise ValueError("conjugate and negative views are unsupported")
    if any(t.device != a.device for t in tensors):
        raise ValueError("all tensors must be on the same device")
    m, k = a.shape
    if m not in supported_m:
        raise ValueError(f"unsupported M={m}; expected one of {supported_m}")
    if k != 1536 or b.shape != (3072, 1536):
        raise ValueError("expected N=3072 and K=1536")
    if a.dtype != torch.float8_e4m3fn or b.dtype != torch.float8_e4m3fn:
        raise ValueError("expected E4M3FN operands")
    if a_scale.dtype != torch.float32 or b_scale.dtype != torch.float32:
        raise ValueError("expected FP32 scales")
    if a_scale.shape != (m, 12) or b_scale.shape != (24, 12):
        raise ValueError("expected activation 1x128 and weight 128x128 scales")
    if getattr(b, "is_shuffled", False):
        raise ValueError("preshuffled weights are unsupported")
